mapper.insert:
insert into note (
	note_no, project_no, note_writer_no,
	note_title, note_content
)
values (
	#{noteNo}, #{projectNo}, #{noteWriterNo},
	#{noteTitle}, #{noteContent}
)

mapper.select:
select * from (
	select rownum rn, TMP.* from (
		select * from note
		where project_no = #{projectNo}




		and note_no < #{lastNo}









					and instr(note_title, #{keyword}) > 0




					and dbms_lob.instr(note_content, #{keyword}) > 0




					and (
						instr(note_title, #{keyword}) > 0
						or dbms_lob.instr(note_content, #{keyword}) > 0
					)




		order by note_no desc
	)TMP
)
where rn between 1 and #{size}

select count(*) from note
where project_no = #{projectNo}



and note_no < #{lastNo}






			and instr(note_title, #{keyword}) > 0


